import AppKit
import SwiftUI

/// Rookery's logo at the top of the sidebar: its crows in their nest beside the name, as pixel art drawn
/// one logo pixel to a point, never smoothed. The art is generated by `branding/` into the app's resources,
/// with a version at twice the size for Retina screens; a build without them shows the name in text.
struct RookeryLogo: View {
    private static let imageName = "SidebarLogo"
    private static let name = "Rookery"
    private static let fallbackFontSize: CGFloat = 15

    var body: some View {
        if let image = NSImage(named: Self.imageName) {
            Image(nsImage: image)
                .interpolation(.none)
                .accessibilityLabel(Self.name)
        } else {
            Text(Self.name)
                .font(.system(size: Self.fallbackFontSize, weight: .bold))
        }
    }
}
